import { Button, useI18n } from '@gntik-ai/ui';
import { Check, Copy, X } from 'lucide-react';
import { useCopy } from '../utils/useCopy';
import { markdownStyles } from './markdown.variants';

const s = markdownStyles.code;

export interface CodeBlockProps {
  /** Source text. */
  code: string;
  /** Language tag from the fence (```ts). */
  language?: string;
  className?: string;
}

/** Fenced code with a language label and a copy button. */
export function CodeBlock({ code, language, className }: CodeBlockProps) {
  const { copied, status, copy } = useCopy();
  const { t } = useI18n();
  return (
    <div className={className ? `${s.root} ${className}` : s.root} data-language={language}>
      <div className={s.header}>
        <span className={s.lang}>{language || 'text'}</span>
        <Button
          size="sm"
          variant="ghost"
          icon={status === 'failed' ? X : copied ? Check : Copy}
          aria-label={status === 'failed' ? t('common.copyFailed') : copied ? t('chat.copiedCode') : t('chat.copyCode')}
          className="h-7 px-2"
          onClick={() => void copy(code)}
        >
          {status === 'failed' ? t('common.copyFailed') : copied ? t('common.copied') : t('common.copy')}
        </Button>
      </div>
      <pre className={s.pre}>
        <code>{code}</code>
      </pre>
    </div>
  );
}

import { cn, useI18n } from '@gntik-ai/ui';
import { ExternalLink } from 'lucide-react';
import { Children, createContext, isValidElement, memo, useContext, type ComponentType, type ReactNode } from 'react';
import ReactMarkdown, { defaultUrlTransform, type Components, type Options } from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { CodeBlock } from './CodeBlock';
import { scanCustomTags, remarkCustomTags, type CustomBlock } from './customTags';
import { useHtmlSubset } from './htmlSubset';
import { markdownStyles as s, streamingCaretClass } from './markdown.variants';

export interface MarkdownProps {
  /** Markdown source (GitHub-flavoured: tables, task lists, strikethrough, autolinks). */
  children: string;
  /** Text is still arriving: closes a dangling code fence and draws the caret. */
  streaming?: boolean;
  className?: string;
  /** Stable component map, merged over the kit defaults. Receives untrusted content. */
  components?: MarkdownComponents;
  codeRenderers?: Record<string, ComponentType<MarkdownCodeRendererProps>>;
  /** Only standalone block tags registered here consume source. */
  customTags?: Record<string, ComponentType<MarkdownCustomTagProps>>;
  /** Opt in to the fixed sanitised HTML subset, loaded asynchronously. */
  allowHtml?: boolean;
  /** Stable plugin arrays, appended after the kit plugins. */
  remarkPlugins?: Options['remarkPlugins'];
  rehypePlugins?: Options['rehypePlugins'];
}

export type MarkdownComponents = Partial<Components>;
export interface MarkdownCodeRendererProps {
  code: string;
  language: string;
  streaming: boolean;
  complete: boolean;
}
export interface MarkdownCustomTagProps {
  children: ReactNode;
  attributes: Record<string, string>;
  streaming: boolean;
  complete: boolean;
}
interface RendererContextValue {
  streaming: boolean;
  codeRenderers?: Record<string, ComponentType<MarkdownCodeRendererProps>>;
  repairedOffset?: number;
  tags?: Record<string, ComponentType<MarkdownCustomTagProps>>;
  blocks?: Record<number, CustomBlock>;
}
const MarkdownContext = createContext<RendererContextValue>({ streaming: false });
/** Stream state for element overrides, code renderers and custom tags. */
export function useMarkdownContext(): { streaming: boolean } {
  return { streaming: useContext(MarkdownContext).streaming };
}

const SAFE_PROTOCOL = /^(https?|mailto|tel):/i;

/**
 * URL policy: relative URLs, anchors and http(s)/mailto/tel only. Everything else
 * (javascript:, data:, vbscript:, …) is dropped, on top of react-markdown's own transform.
 */
export function safeUrl(url: string): string {
  const cleaned = defaultUrlTransform(url);
  if (!cleaned) return '';
  // Ignore whitespace and control characters browsers skip ("java\tscript:").
  const compact = Array.from(cleaned)
    .filter((c) => c.charCodeAt(0) > 0x20)
    .join('');
  if (/^[a-z][a-z0-9+.-]*:/i.test(compact) && !SAFE_PROTOCOL.test(compact)) return '';
  return cleaned;
}

/**
 * Makes partial streamed markdown render sanely: a fence that has opened but not closed is
 * closed at the end, so the tail renders as code instead of flashing as paragraphs.
 */
export function repairStreamingMarkdown(text: string): string {
  const fences = text.match(/^ {0,3}(`{3,}|~{3,})/gm) ?? [];
  if (fences.length % 2 === 0) return text;
  const opener = (fences[fences.length - 1] ?? '```').trim();
  return `${text}${text.endsWith('\n') ? '' : '\n'}${opener}`;
}

const isExternal = (href: string) => /^https?:\/\//i.test(href);

/** Drops react-markdown's `node` (hast) prop before spreading onto a DOM element. */
/** Screen-reader note on links that open a new tab. */
function NewTabHint() {
  const { t } = useI18n();
  return <span className="sr-only"> {t('link.external')}</span>;
}

/** Remote images can track readers and break layout mid-stream: show them as links. */
function ImageLink({ href, alt }: { href: string; alt?: string }) {
  const { t } = useI18n();
  const text = t('chat.image', { alt: alt || t('chat.untitled') });
  return href ? (
    <a href={href} target="_blank" rel="noopener noreferrer nofollow" className={s.link}>
      {text}
      <NewTabHint />
    </a>
  ) : (
    <span className={s.image}>{text}</span>
  );
}

function TaskCheckbox({ checked }: { checked: boolean }) {
  const { t } = useI18n();
  return (
    <input
      type="checkbox"
      checked={checked}
      readOnly
      disabled
      aria-label={checked ? t('chat.taskDone') : t('chat.taskNotDone')}
      className={s.checkbox}
    />
  );
}

function omitNode<T extends { node?: unknown }>(props: T): Omit<T, 'node'> {
  const { node, ...rest } = props;
  void node;
  return rest;
}

type CodeChildProps = { className?: string; children?: ReactNode };

const CodeRenderer: Components['pre'] = ({ children, node }) => {
  const { streaming, codeRenderers: renderers, repairedOffset } = useContext(MarkdownContext);
  const child = Children.toArray(children)[0];
  if (!isValidElement<CodeChildProps>(child)) return <pre className={s.code.pre}>{children}</pre>;
  const language = /language-([\w+#.-]+)/.exec(child.props.className ?? '')?.[1];
  const code = String(Children.toArray(child.props.children).join('')).replace(/\n$/, '');
  const Renderer = language ? renderers?.[language.toLowerCase()] : undefined;
  return Renderer && language ? (
    <Renderer
      code={code}
      language={language.toLowerCase()}
      streaming={streaming}
      complete={node?.position?.start.offset !== repairedOffset}
    />
  ) : (
    <CodeBlock code={code} language={language} />
  );
};

const CustomTagRenderer: Components['div'] = ({ children, node, ...props }) => {
  const { streaming, tags, blocks } = useContext(MarkdownContext);
  const id = node?.properties.dataMarkdownTag;
  const block = typeof id === 'number' || typeof id === 'string' ? blocks?.[Number(id)] : undefined;
  const Tag = block && tags?.[block.name];
  return Tag && block ? (
    <Tag attributes={block.attributes} streaming={streaming} complete={block.complete}>
      {children}
    </Tag>
  ) : (
    <div {...props}>{children}</div>
  );
};

const customTagComponents = { 'markdown-custom-tag': CustomTagRenderer };

const kitComponents: Components = {
  pre: CodeRenderer,
  h1: (p) => <h1 {...omitNode(p)} className={s.h1} />,
  h2: (p) => <h2 {...omitNode(p)} className={s.h2} />,
  h3: (p) => <h3 {...omitNode(p)} className={s.h3} />,
  h4: (p) => <h4 {...omitNode(p)} className={s.h4} />,
  h5: (p) => <h4 {...omitNode(p)} className={s.h4} />,
  h6: (p) => <h4 {...omitNode(p)} className={s.h4} />,
  p: (p) => <p {...omitNode(p)} className={s.p} />,
  ul: (p) => <ul {...omitNode(p)} className={cn(s.ul, p.className === 'contains-task-list' && 'ps-1')} />,
  ol: (p) => <ol {...omitNode(p)} className={s.ol} />,
  li: (p) => <li {...omitNode(p)} className={cn(s.li, p.className)} />,
  blockquote: (p) => <blockquote {...omitNode(p)} className={s.blockquote} />,
  hr: () => <hr className={s.hr} />,
  table: (p) => (
    <div className={s.tableWrap}>
      <table {...omitNode(p)} className={s.table} />
    </div>
  ),
  th: (p) => <th {...omitNode(p)} className={s.th} />,
  td: (p) => <td {...omitNode(p)} className={s.td} />,
  a: (props) => {
    const { href, children, ...p } = omitNode(props);
    if (!href) return <span>{children}</span>;
    if (!isExternal(href)) {
      return (
        <a href={href} className={s.link} {...p}>
          {children}
        </a>
      );
    }
    return (
      <a href={href} target="_blank" rel="noopener noreferrer nofollow" className={s.link} {...p}>
        {children}
        <ExternalLink size={12} aria-hidden className={s.linkIcon} />
        <NewTabHint />
      </a>
    );
  },
  img: ({ src, alt }) => <ImageLink href={typeof src === 'string' ? src : ''} alt={alt} />,
  input: ({ checked, type }) => (type === 'checkbox' ? <TaskCheckbox checked={!!checked} /> : null),
  code: ({ className, children }) => <code className={cn(s.inlineCode, className)}>{children}</code>,
};

function lowercaseKeys<T>(values: Record<string, T> | undefined): Record<string, T> {
  const result: Record<string, T> = Object.create(null);
  for (const [key, value] of Object.entries(values ?? {})) result[key.toLowerCase()] = value;
  return result;
}

/**
 * Safe markdown for model output: raw HTML is skipped by default, links are
 * restricted to http(s)/mailto/tel/relative, external links open in a new tab with a marker,
 * and fenced code gets a copy button. Partial input from a stream is tolerated.
 */
function MarkdownContent({
  children,
  streaming = false,
  components,
  codeRenderers,
  remarkPlugins,
  rehypePlugins,
  htmlPlugins,
  customTags,
}: MarkdownProps & { htmlPlugins?: Options['rehypePlugins'] }) {
  const tags = lowercaseKeys(customTags);
  const custom = scanCustomTags(children, new Set(Object.keys(tags)), streaming);
  const source = streaming ? repairStreamingMarkdown(custom.source) : custom.source;
  const repairedFence =
    source === custom.source ? undefined : Array.from(custom.source.matchAll(/^ {0,3}(`{3,}|~{3,})/gm)).at(-1);
  // HAST starts the code node at the marker, after any permitted indentation.
  const repairedOffset = repairedFence ? repairedFence.index + repairedFence[0].search(/[`~]/) : -1;
  const renderers = lowercaseKeys(codeRenderers);
  return (
    <MarkdownContext.Provider
      value={{ streaming, codeRenderers: renderers, repairedOffset, tags, blocks: custom.byId }}
    >
      <ReactMarkdown
        remarkPlugins={[remarkGfm, remarkCustomTags(custom.blocks), ...(remarkPlugins ?? [])]}
        rehypePlugins={[...(htmlPlugins ?? []), ...(rehypePlugins ?? [])]}
        components={{ ...kitComponents, ...components, ...customTagComponents }}
        skipHtml
        urlTransform={safeUrl}
      >
        {source}
      </ReactMarkdown>
    </MarkdownContext.Provider>
  );
}

export const Markdown = memo(function Markdown({
  children,
  streaming = false,
  className,
  customTags,
  allowHtml = false,
  ...props
}: MarkdownProps) {
  const htmlPlugins = useHtmlSubset(allowHtml);
  return (
    <div data-streaming={streaming || undefined} className={cn(s.root, streaming && streamingCaretClass, className)}>
      <MarkdownContent {...props} customTags={customTags} streaming={streaming} htmlPlugins={htmlPlugins}>
        {children}
      </MarkdownContent>
    </div>
  );
});

export interface CustomBlock {
  id: number;
  name: string;
  attributes: Record<string, string>;
  complete: boolean;
  start: number;
  end: number;
  children: CustomBlock[];
}

interface MarkdownNode {
  type: string;
  children?: MarkdownNode[];
  position?: { start: { offset?: number } };
  data?: { hName: string; hProperties: Record<string, number> };
}

/** Wrap the already-parsed blocks, keeping definitions in the same Markdown document. */
export function remarkCustomTags(blocks: CustomBlock[]) {
  function wrap(nodes: MarkdownNode[], ranges: CustomBlock[]): MarkdownNode[] {
    const result: MarkdownNode[] = [];
    let cursor = 0;
    for (const block of ranges) {
      while (cursor < nodes.length && (nodes[cursor]!.position?.start.offset ?? Infinity) < block.start)
        result.push(nodes[cursor++]!);
      const children: MarkdownNode[] = [];
      while (cursor < nodes.length && (nodes[cursor]!.position?.start.offset ?? Infinity) < block.end)
        children.push(nodes[cursor++]!);
      result.push({
        type: 'markdownCustomTag',
        data: { hName: 'markdown-custom-tag', hProperties: { dataMarkdownTag: block.id } },
        children: wrap(children, block.children),
      });
    }
    return result.concat(nodes.slice(cursor));
  }
  return () => (tree: MarkdownNode) => {
    tree.children = wrap(tree.children ?? [], blocks);
  };
}

interface TagLine {
  start: number;
  end: number;
  name: string;
  closing: boolean;
  attributes: Record<string, string>;
  close?: number;
}

/** Sticky tokenisation never retries a malformed attribute at every later character. */
function attributesFrom(text: string): Record<string, string> | undefined {
  const attributes: Record<string, string> = Object.create(null);
  const attribute = /\s+([a-z_:][\w:.-]*)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/giy;
  let offset = 0;
  while (offset < text.length) {
    attribute.lastIndex = offset;
    const match = attribute.exec(text);
    if (!match) return text.slice(offset).trim() ? undefined : attributes;
    offset = attribute.lastIndex;
    const name = match[1]!.toLowerCase();
    if (name !== 'style' && !name.startsWith('on')) attributes[name] = match[2] ?? match[3] ?? match[4] ?? '';
  }
  return attributes;
}

/**
 * Scan whole lines once, outside fences. Only registered, paired blocks (or a streaming
 * partial block) consume source. Every other byte stays in the normal Markdown pipeline.
 * Pairing first avoids reparsing arbitrary CommonMark HTML nodes or repeatedly searching tails.
 */
export function scanCustomTags(source: string, names: ReadonlySet<string>, streaming: boolean) {
  const byId: Record<number, CustomBlock> = Object.create(null);
  if (!names.size) return { source, blocks: [], byId };
  const tags: TagLine[] = [];
  let offset = 0;
  let fence: { marker: string; length: number } | undefined;
  for (const line of source.split('\n')) {
    const end = Math.min(source.length, offset + line.length + 1);
    const delimiter = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (delimiter) {
      const marker = delimiter[1]!;
      if (!fence) fence = { marker: marker[0]!, length: marker.length };
      else if (marker[0] === fence.marker && marker.length >= fence.length && !delimiter[2]!.trim()) fence = undefined;
    } else if (!fence) {
      const tag = /^ {0,3}<(\/?)([a-z][\w-]*)(?=[\s>])/i.exec(line);
      const name = tag?.[2]?.toLowerCase();
      const tail = line.trimEnd();
      if (tag && name && names.has(name) && tail.endsWith('>')) {
        const closing = tag[1] === '/';
        const text = tail.slice(tag[0].length, -1);
        const attributes = closing ? (text.trim() ? undefined : {}) : attributesFrom(text);
        if (attributes) tags.push({ start: offset, end, name, closing, attributes });
      }
    }
    offset = end;
  }
  const closes = new Map<string, number[]>();
  for (let i = tags.length - 1; i >= 0; i--) {
    const tag = tags[i]!;
    const pending = closes.get(tag.name) ?? [];
    if (tag.closing) {
      pending.push(i);
      closes.set(tag.name, pending);
    } else tag.close = pending.pop();
  }
  const masks: { start: number; end: number }[] = [];
  function blocks(end: number, from: number, to: number): CustomBlock[] {
    const result: CustomBlock[] = [];
    for (let i = from; i < to; i++) {
      const tag = tags[i]!;
      if (tag.closing) continue;
      const close = tag.close !== undefined && tag.close < to ? tags[tag.close] : undefined;
      if (!close && !streaming) continue;
      masks.push(tag);
      const block: CustomBlock = {
        id: i,
        name: tag.name,
        attributes: tag.attributes,
        complete: !!close,
        start: tag.start,
        end: close?.end ?? end,
        children: blocks(close?.start ?? end, i + 1, close ? tag.close! : to),
      };
      if (close) masks.push(close);
      byId[block.id] = block;
      result.push(block);
      i = close ? tag.close! : to;
    }
    return result;
  }
  const ranges = blocks(source.length, 0, tags.length);
  const parts: string[] = [];
  let cursor = 0;
  for (const mask of masks) {
    parts.push(source.slice(cursor, mask.start), source.slice(mask.start, mask.end).replace(/[^\r\n]/g, ' '));
    cursor = mask.end;
  }
  parts.push(source.slice(cursor));
  // Preserve every source offset (including code fences) and parse exactly once. Only valid
  // registered delimiters become blank lines; unknown HTML retains CommonMark handling.
  return { source: parts.join(''), blocks: ranges, byId };
}

import { useEffect, useState } from 'react';
import type { Options } from 'react-markdown';
import type rehypeRaw from 'rehype-raw';
import type { Options as SanitizeSchema } from 'rehype-sanitize';

type HtmlTree = Parameters<ReturnType<typeof rehypeRaw>>[0];
type HtmlFile = Parameters<ReturnType<typeof rehypeRaw>>[1];
type HtmlNode = HtmlTree['children'][number];
type HtmlElement = Extract<HtmlNode, { type: 'element' }>;
type Plugins = NonNullable<Options['rehypePlugins']>;

const subset = [
  'b',
  'strong',
  'i',
  'em',
  'u',
  's',
  'del',
  'sub',
  'sup',
  'kbd',
  'mark',
  'abbr',
  'br',
  'details',
  'summary',
];
const dropContent = new Set([
  'script',
  'style',
  'iframe',
  'object',
  'embed',
  'form',
  'audio',
  'video',
  'source',
  'track',
  'picture',
  'img',
  'svg',
  'math',
  'template',
  'textarea',
]);
// Private fixed schema: consumers cannot widen it. Markdown-generated elements keep their
// normal semantics; raw elements first pass the narrower subset policy below.
const schema: SanitizeSchema = {
  tagNames: [
    ...subset,
    'a',
    'p',
    'h1',
    'h2',
    'h3',
    'h4',
    'h5',
    'h6',
    'blockquote',
    'ul',
    'ol',
    'li',
    'hr',
    'pre',
    'code',
    'table',
    'thead',
    'tbody',
    'tr',
    'th',
    'td',
    'input',
    'img',
    'section',
    'div',
    'markdown-custom-tag',
  ],
  attributes: {
    '*': [],
    a: ['href', 'title', 'id', 'dataFootnoteRef', 'dataFootnoteBackref', 'ariaDescribedBy', 'ariaLabel'],
    abbr: ['title'],
    details: ['open'],
    'markdown-custom-tag': ['dataMarkdownTag'],
    code: [['className', /^language-/]],
    ol: ['start'],
    ul: [['className', 'contains-task-list']],
    li: [['className', 'task-list-item']],
    input: [['type', 'checkbox'], 'checked', 'disabled'],
    img: ['src', 'alt', 'title'],
    th: ['align'],
    td: ['align'],
    section: ['dataFootnotes'],
    h2: ['id', ['className', 'sr-only']],
  },
  protocols: { href: ['http', 'https', 'mailto', 'tel'], src: ['http', 'https'] },
  strip: [...dropContent].filter((tag) => tag !== 'img'),
};

function origin(node: HtmlElement): string {
  return `${node.tagName}:${node.position?.start.offset}`;
}

function collectMarkdown(node: HtmlTree | HtmlNode, origins: Set<string>): void {
  if (node.type === 'element') origins.add(origin(node));
  if ('children' in node) for (const child of node.children) collectMarkdown(child, origins);
}

function filterRaw(node: HtmlTree | HtmlElement, markdown: ReadonlySet<string>): void {
  const children: typeof node.children = [];
  for (const child of node.children) {
    if (child.type === 'doctype') continue;
    if (child.type !== 'element') {
      children.push(child);
      continue;
    }
    const fromMarkdown = markdown.has(origin(child));
    if (!fromMarkdown && dropContent.has(child.tagName)) continue;
    filterRaw(child, markdown);
    if (fromMarkdown || subset.includes(child.tagName)) children.push(child);
    else children.push(...child.children);
  }
  node.children = children;
}

let loaded: Plugins | undefined;
let loading: Promise<Plugins> | undefined;
function loadHtmlSubset(): Promise<Plugins> {
  return (loading ??= Promise.all([import('rehype-raw'), import('rehype-sanitize')]).then(([raw, sanitize]) => {
    const parse = raw.default();
    const clean = sanitize.default(schema);
    loaded = [
      () => (tree: HtmlTree, file: HtmlFile) => {
        const markdown = new Set<string>();
        collectMarkdown(tree, markdown);
        const parsed = parse(tree, file);
        filterRaw(parsed, markdown);
        return clean(parsed);
      },
    ];
    return loaded;
  }));
}

/** Until both optional parsers load, ReactMarkdown continues to skip raw HTML. */
export function useHtmlSubset(enabled: boolean): Plugins | undefined {
  const [plugins, setPlugins] = useState(() => (enabled ? loaded : undefined));
  useEffect(() => {
    if (!enabled) return;
    let active = true;
    void loadHtmlSubset().then(
      (value) => {
        if (active) setPlugins(value);
      },
      () => {},
    );
    return () => {
      active = false;
    };
  }, [enabled]);
  return enabled ? plugins : undefined;
}

export {
  Markdown,
  repairStreamingMarkdown,
  safeUrl,
  useMarkdownContext,
  type MarkdownProps,
  type MarkdownComponents,
  type MarkdownCodeRendererProps,
  type MarkdownCustomTagProps,
} from './Markdown';
export { CodeBlock, type CodeBlockProps } from './CodeBlock';
export { markdownStyles, streamingCaretClass } from './markdown.variants';
export { doc as markdownDoc } from './Markdown.doc';

import { useCallback, useEffect, useRef, useState } from 'react';

/**
 * Copies text to the clipboard and exposes a short-lived status and compatible `copied` flag for the button label.
 * The reset timer is cleared on unmount and on every new copy.
 */
export function useCopy(resetMs = 1600) {
  const [status, setStatus] = useState<'idle' | 'copied' | 'failed'>('idle');
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  const mounted = useRef(true);
  const attempt = useRef(0);
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      attempt.current += 1;
      clearTimeout(timer.current);
    };
  }, []);

  const copy = useCallback(
    async (text: string) => {
      clearTimeout(timer.current);
      const current = ++attempt.current;
      let next: 'copied' | 'failed' = 'failed';
      try {
        if (navigator.clipboard?.writeText) {
          await navigator.clipboard.writeText(text);
          next = 'copied';
        }
      } catch {
        // Permission errors and unavailable clipboard access both report failure.
      }
      if (!mounted.current || current !== attempt.current) return;
      setStatus(next);
      timer.current = setTimeout(() => setStatus('idle'), resetMs);
    },
    [resetMs],
  );

  return { status, copied: status === 'copied', copy };
}

import type { ComponentDoc } from '@gntik-ai/ui';

export const doc: ComponentDoc = {
  name: 'Markdown',
  group: 'Display',
